/**
 * Cashfree Payments for FluentCart Checkout Handler
 * Follows the official FluentCart payment gateway standard
 */
(function () {
    "use strict";

    let activeInstance = null;
    let isOpening = false;

    class CashfreeCheckout {
        constructor(form, orderHandler, response, paymentLoader) {
            this.form = form;
            this.orderHandler = orderHandler;
            this.data = response || {};
            this.paymentLoader = paymentLoader;
            this.$t = this.translate.bind(this);
            this.submitButton = window.fluentcart_checkout_vars?.submit_button;
        }

        init() {
            const submitText = this.translate(this.submitButton?.text || 'Place Order');
            if (this.paymentLoader && typeof this.paymentLoader.enableCheckoutButton === 'function') {
                this.paymentLoader.enableCheckoutButton(submitText);
            }

            const container = document.querySelector('.fluent-cart-checkout_embed_payment_container_cashfree');
            const hasCustomContent = container && container.dataset.hasCustomContent === 'true';
            if (container && !hasCustomContent) {
                container.innerHTML = '';
                this.renderPaymentInfo(container);
                container.dataset.hasCustomContent = 'true';
            }
        }

        translate(string) {
            const translations = window.fct_cashfree_data?.translations || {};
            return translations[string] || string;
        }

        getPaymentMethodIcons() {
            return {
                cards: '<svg xmlns="http://www.w3.org/2000/svg" width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="1" y="4" width="22" height="16" rx="2" ry="2"></rect><line x1="1" y1="10" x2="23" y2="10"></line></svg>',
                upi: '<img width="28" height="28" src="https://img.icons8.com/color/48/bhim.png" alt="bhim" loading="lazy" decoding="async" />',
                netbanking: '<svg xmlns="http://www.w3.org/2000/svg" width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M3 21h18"></path><path d="M3 10h18"></path><path d="M5 6l7-3 7 3"></path><path d="M4 10v11"></path><path d="M20 10v11"></path><path d="M8 14v3"></path><path d="M12 14v3"></path><path d="M16 14v3"></path></svg>',
                wallets: '<svg xmlns="http://www.w3.org/2000/svg" width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12V7H5a2 2 0 0 1 0-4h14v4"></path><path d="M3 5v14a2 2 0 0 0 2 2h16v-5"></path><path d="M18 12a2 2 0 0 0 0 4h4v-4Z"></path></svg>'
            };
        }

        renderPaymentInfo(container) {
            if (!container) return;

            const icons = this.getPaymentMethodIcons();
            const methods = [
                { key: 'cards', icon: icons.cards, label: this.$t('Cards') },
                { key: 'upi', icon: icons.upi, label: this.$t('UPI') },
                { key: 'netbanking', icon: icons.netbanking, label: this.$t('Net Banking') },
                { key: 'wallets', icon: icons.wallets, label: this.$t('Wallets') }
            ];

            let html = '<div class="fct-cashfree-info">';
            html += '<div class="fct-cashfree-header">';
            html += '<p class="fct-cashfree-subheading">' + this.$t('Available payment methods') + '</p>';
            html += '</div>';
            html += '<div class="fct-cashfree-methods">';
            methods.forEach(m => {
                html += '<div class="fct-cashfree-method" title="' + m.label + '">';
                html += '<span class="fct-method-icon">' + m.icon + '</span>';
                html += '<span class="fct-method-name">' + m.label + '</span>';
                html += '</div>';
            });
            html += '</div></div>';

            html += '<style>' +
                '.fct-cashfree-info {' +
                    'padding: 16px;' +
                    'border: 1px solid #e2e8f0;' +
                    'border-radius: 8px;' +
                    'background: #f8fafc;' +
                    'margin: 10px 0 16px 0;' +
                    'box-sizing: border-box;' +
                '}' +
                ':is(html.dark, body.dark, .dark, [data-theme="dark"]) .fct-cashfree-info {' +
                    'background: #1e293b;' +
                    'border-color: #334155;' +
                '}' +
                '.fct-cashfree-header {' +
                    'text-align: center;' +
                    'margin-bottom: 12px;' +
                '}' +
                '.fct-cashfree-subheading {' +
                    'margin: 0;' +
                    'font-size: 11px;' +
                    'color: #64748b;' +
                    'font-weight: 600;' +
                    'letter-spacing: 0.5px;' +
                    'text-transform: uppercase;' +
                '}' +
                ':is(html.dark, body.dark, .dark, [data-theme="dark"]) .fct-cashfree-subheading {' +
                    'color: #94a3b8;' +
                '}' +
                '.fct-cashfree-methods {' +
                    'display: flex;' +
                    'flex-wrap: wrap;' +
                    'justify-content: center;' +
                    'gap: 10px;' +
                '}' +
                '.fct-cashfree-method {' +
                    'display: flex;' +
                    'flex-direction: column;' +
                    'align-items: center;' +
                    'justify-content: center;' +
                    'padding: 10px 14px;' +
                    'background: #ffffff;' +
                    'border: 1px solid #cbd5e1;' +
                    'border-radius: 8px;' +
                    'transition: all 0.2s ease;' +
                    'min-width: 68px;' +
                    'box-shadow: 0 1px 2px rgba(0, 0, 0, 0.04);' +
                '}' +
                ':is(html.dark, body.dark, .dark, [data-theme="dark"]) .fct-cashfree-method {' +
                    'background: #0f172a;' +
                    'border-color: #334155;' +
                '}' +
                '.fct-cashfree-method:hover {' +
                    'border-color: #6C2BD9;' +
                    'box-shadow: 0 2px 8px rgba(108, 43, 217, 0.15);' +
                '}' +
                '.fct-method-icon {' +
                    'display: flex;' +
                    'align-items: center;' +
                    'justify-content: center;' +
                    'color: #6C2BD9;' +
                    'margin-bottom: 4px;' +
                '}' +
                ':is(html.dark, body.dark, .dark, [data-theme="dark"]) .fct-method-icon {' +
                    'color: #a78bfa;' +
                '}' +
                '.fct-method-icon img {' +
                    'width: 28px;' +
                    'height: 28px;' +
                    'object-fit: contain;' +
                    'display: block;' +
                '}' +
                '.fct-method-name {' +
                    'font-size: 11px;' +
                    'font-weight: 500;' +
                    'color: #475569;' +
                    'text-align: center;' +
                '}' +
                ':is(html.dark, body.dark, .dark, [data-theme="dark"]) .fct-method-name {' +
                    'color: #cbd5e1;' +
                '}' +
                '@media (max-width: 768px) {' +
                    '.fct-cashfree-info { padding: 12px; }' +
                    '.fct-cashfree-methods { gap: 8px; }' +
                    '.fct-cashfree-method { padding: 8px 10px; min-width: 58px; }' +
                    '.fct-method-icon svg, .fct-method-icon img { width: 22px; height: 22px; }' +
                    '.fct-method-name { font-size: 10px; }' +
                '}' +
            '</style>';

            container.innerHTML = html;
        }
    }

    function loadCashfreeSDK() {
        if (typeof window.Cashfree === 'function') {
            return Promise.resolve();
        }
        return new Promise((resolve, reject) => {
            const existing = document.querySelector('script[src*="cashfree.com/js/v3/cashfree.js"]');
            if (existing) {
                let count = 0;
                const interval = setInterval(() => {
                    count++;
                    if (typeof window.Cashfree === 'function') {
                        clearInterval(interval);
                        resolve();
                    } else if (count > 30) {
                        clearInterval(interval);
                        reject(new Error('Cashfree SDK timeout'));
                    }
                }, 100);
                return;
            }
            const script = document.createElement('script');
            script.src = 'https://sdk.cashfree.com/js/v3/cashfree.js';
            script.onload = () => resolve();
            script.onerror = () => reject(new Error('Failed to load Cashfree Checkout SDK.'));
            document.head.appendChild(script);
        });
    }

    async function postAjax(url, data) {
        const response = await fetch(url, {
            method: 'POST',
            credentials: 'same-origin',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded;charset=UTF-8' },
            body: new URLSearchParams(data)
        });
        return await response.json();
    }

    // Checkout initialization event
    function handleLoadPayments(e) {
        const container = document.querySelector('.fluent-cart-checkout_embed_payment_container_cashfree');
        if (container && container.children.length > 0 && container.dataset.hasCustomContent === 'true') {
            const submitText = window.fluentcart_checkout_vars?.submit_button?.text || 'Place Order';
            e.detail?.paymentLoader?.enableCheckoutButton(submitText);
            return;
        }

        const infoUrl = e.detail?.paymentInfoUrl;
        const nonce = e.detail?.nonce;

        if (infoUrl && nonce) {
            fetch(infoUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'X-WP-Nonce': nonce
                },
                credentials: 'include'
            }).then(async (res) => {
                const data = await res.json();
                activeInstance = new CashfreeCheckout(e.detail?.form, e.detail?.orderHandler, data, e.detail?.paymentLoader);
                activeInstance.init();
            }).catch(() => {
                activeInstance = new CashfreeCheckout(e.detail?.form, e.detail?.orderHandler, {}, e.detail?.paymentLoader);
                activeInstance.init();
            });
        } else {
            activeInstance = new CashfreeCheckout(e.detail?.form, e.detail?.orderHandler, {}, e.detail?.paymentLoader);
            activeInstance.init();
        }
    }

    // Payment action event (modal popup launcher)
    async function handlePaymentAction(e) {
        if (isOpening) return;
        isOpening = true;

        const paymentLoader = activeInstance?.paymentLoader;
        const submitBtnText = window.fluentcart_checkout_vars?.submit_button?.text || 'Place Order';

        function resetCheckout() {
            isOpening = false;
            try { paymentLoader?.hideLoader(); } catch (err) {}
            try { paymentLoader?.showCheckoutButton(); } catch (err) {}
            try { paymentLoader?.enableCheckoutButton(submitBtnText); } catch (err) {}
        }

        function notifyError(msg) {
            resetCheckout();
            console.error('Cashfree Payments Error:', msg);
            const fc = window.fluentcart || window.FluentCart;
            if (fc && typeof fc.notify === 'function') {
                fc.notify(msg, 'error');
            } else {
                alert(msg);
            }
        }

        const detail = e.detail || {};

        // 1. Direct failure checks
        if (detail.status === 'failed' || detail.status === 'error') {
            notifyError(detail.message || 'Payment initiation failed. Please try again.');
            return;
        }

        const rawResponse = detail.response || detail.payment_args || detail.data?.response || detail.data?.payment_args || detail.data || detail.payment_response || detail;

        if (rawResponse?.status === 'failed' || rawResponse?.status === 'error') {
            notifyError(rawResponse.message || 'Payment initiation failed. Please try again.');
            return;
        }

        // 2. Extract payload
        const payload = rawResponse?.payment_args || rawResponse?.response || rawResponse?.data || rawResponse;

        if (payload?.status === 'failed' || payload?.status === 'error') {
            notifyError(payload.message || 'Payment initiation failed. Please try again.');
            return;
        }

        const txUuid = payload?.transaction_uuid || payload?.transaction_hash || rawResponse?.transaction_uuid || detail?.transaction_uuid;
        const paymentSessionId = payload?.payment_session_id || rawResponse?.payment_session_id;
        const subscriptionSessionId = payload?.subscription_session_id || rawResponse?.subscription_session_id;
        const isSub = (payload?.type === 'subscription') || (rawResponse?.type === 'subscription') || Boolean(subscriptionSessionId);
        const orderId = payload?.cashfree_order_id || rawResponse?.cashfree_order_id || '';
        const mode = payload?.mode || rawResponse?.mode || window.fct_cashfree_data?.mode || 'production';
        const ajaxUrl = payload?.ajax_url || rawResponse?.ajax_url || window.fluentcart_checkout_vars?.ajaxurl || '/wp-admin/admin-ajax.php';
        const nonce = payload?.nonce || rawResponse?.nonce || '';

        try {
            if (isSub && !subscriptionSessionId) {
                throw new Error(payload?.message || rawResponse?.message || detail?.message || 'Cashfree subscription session was not returned by server.');
            }
            if (!isSub && !paymentSessionId) {
                throw new Error(payload?.message || rawResponse?.message || detail?.message || 'Cashfree payment session was not returned by server.');
            }

            const openingMsg = activeInstance?.translate('Payment Modal is opening...') || 'Payment Modal is opening, please complete the payment...';
            try { paymentLoader?.changeLoaderStatus(openingMsg); } catch (err) {}

            await loadCashfreeSDK();

            const cashfree = window.Cashfree({
                mode: mode === 'sandbox' ? 'sandbox' : 'production'
            });

            const checkoutPromise = isSub
                ? cashfree.subscriptionsCheckout({ subsSessionId: subscriptionSessionId, redirectTarget: '_modal' })
                : cashfree.checkout({ paymentSessionId: paymentSessionId, redirectTarget: '_modal' });

            const result = await checkoutPromise;

            if (result && result.redirect) {
                return;
            }

            // Check if user dismissed / cancelled
            if (result && result.error) {
                const errCode = String(result.error.code || '').toLowerCase();
                const errMsg = String(result.error.message || '').toLowerCase();
                const isDismissed = errCode.includes('cancel') || errCode.includes('close') || errCode.includes('dismiss') || errCode.includes('popup') ||
                                    errMsg.includes('cancel') || errMsg.includes('close') || errMsg.includes('dismiss') || errMsg.includes('not completed') ||
                                    errMsg.includes('aborted') || errMsg.includes('drop') || errMsg === '';

                if (txUuid) {
                    try {
                        const check = await postAjax(ajaxUrl, {
                            action: 'cffc_confirm_payment',
                            transaction_id: txUuid,
                            cashfree_order_id: orderId,
                            _ajax_nonce: nonce
                        });
                        if (check?.success && check?.data?.redirect_url) {
                            window.location.href = check.data.redirect_url;
                            return;
                        }
                    } catch (ignored) {}
                }

                if (isDismissed) {
                    resetCheckout();
                    return;
                }

                throw new Error(result.error.message || 'Payment could not be completed.');
            }

            // Modal completed with payment details or subscription
            const procMsg = activeInstance?.translate('Processing payment...') || 'Processing payment...';
            try { paymentLoader?.changeLoaderStatus(procMsg); } catch (err) {}

            if (txUuid) {
                const confirmRes = await postAjax(ajaxUrl, {
                    action: 'cffc_confirm_payment',
                    transaction_id: txUuid,
                    cashfree_order_id: orderId,
                    _ajax_nonce: nonce
                });

                if (confirmRes?.success && confirmRes?.data?.redirect_url) {
                    window.location.href = confirmRes.data.redirect_url;
                    return;
                }

                // Fallback polling if verification is still pending
                for (let i = 0; i < 15; i++) {
                    await new Promise(r => setTimeout(r, 1500));
                    try {
                        const poll = await postAjax(ajaxUrl, {
                            action: 'cffc_payment_status',
                            transaction_id: txUuid,
                            _ajax_nonce: nonce
                        });
                        const pollData = poll?.data || {};
                        if (poll?.success && pollData.transaction_status === 'succeeded' && pollData.redirect_url) {
                            window.location.href = pollData.redirect_url;
                            return;
                        }
                        if (poll?.success && ['failed', 'canceled', 'cancelled'].includes(pollData.transaction_status)) {
                            resetCheckout();
                            return;
                        }
                    } catch (e) {}
                }
            }

            resetCheckout();
        } catch (err) {
            notifyError(err.message || 'Payment error occurred.');
        } finally {
            isOpening = false;
        }
    }

    // Attach listeners
    window.addEventListener('fluent_cart_load_payments_cashfree', handleLoadPayments);
    document.addEventListener('fluent_cart_load_payments_cashfree', handleLoadPayments);

    window.addEventListener('fluent_cart_payment_next_action_cashfree', handlePaymentAction);
    document.addEventListener('fluent_cart_payment_next_action_cashfree', handlePaymentAction);

    // Reset button on payment method change or checkout reset
    document.addEventListener('change', function (e) {
        if (e.target && (e.target.name === 'payment_method' || (e.target.type === 'radio' && e.target.name && e.target.name.includes('payment')))) {
            const submitText = window.fluentcart_checkout_vars?.submit_button?.text || 'Place Order';
            activeInstance?.paymentLoader?.enableCheckoutButton(submitText);
        }
    }, true);

    window.addEventListener('fluent_cart_payment_method_changed', function () {
        const submitText = window.fluentcart_checkout_vars?.submit_button?.text || 'Place Order';
        activeInstance?.paymentLoader?.enableCheckoutButton(submitText);
    });

    window.addEventListener('fluent_cart_checkout_reset', function () {
        const submitText = window.fluentcart_checkout_vars?.submit_button?.text || 'Place Order';
        activeInstance?.paymentLoader?.enableCheckoutButton(submitText);
    });
})();
